"use client";

import { Canvas } from "@react-three/fiber";
import { Suspense } from "react";
import Scene from "./Scene";

export default function MountainTransition() {
  return (
    <div className="relative h-full w-full bg-black">
      {/* 
        Scroll container:
        We make this very tall to allow scrolling.
        The Canvas will be fixed behind it.
      */}
      <div
        className="absolute top-0 left-0 z-10 w-full"
        id="mountain-scroll-container"
        style={{ height: "500vh" }} // 5 sections approx
      />

      {/* 
              Visual Container:
              Fixed to viewport, but with padding and rounded corners to create the "Dashboard/Card" look.
              The scroll container above still drives the window scroll, which GSAP picks up.
            */}
      <div className="fixed inset-0 z-0 flex items-center justify-center bg-[#0a0a0a] p-4">
        <div className="relative h-full w-full overflow-hidden rounded-[32px] border border-white/10 bg-black shadow-2xl">
          <Canvas
            camera={{ zoom: 1, position: [0, 0, 1] }}
            className="absolute inset-0 h-full w-full"
            dpr={[1, 2]}
            gl={{ antialias: true }}
            orthographic
          >
            <Suspense fallback={null}>
              <Scene />
            </Suspense>
          </Canvas>

          {/* Optional: Add a subtle logo or overlay inside the card if needed later */}
        </div>
      </div>
    </div>
  );
}

"use client";

import { shaderMaterial, useTexture, useVideoTexture } from "@react-three/drei";
import { useFrame, useThree } from "@react-three/fiber";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import type React from "react";
import { useEffect, useMemo, useRef } from "react";
import * as THREE from "three";
import { fragmentShader, vertexShader } from "./shaders";

gsap.registerPlugin(ScrollTrigger);

const TransitionMaterial = shaderMaterial(
  {
    uProgress: 0,
    uTime: 0,
    uTex0: new THREE.Texture(),
    uTex1: new THREE.Texture(),
    uTex2: new THREE.Texture(),
    uTex3: new THREE.Texture(),
    uTex4: new THREE.Texture(),
    uDepth: new THREE.Texture(),
    uDisplacementStrength: 0.5,
  },
  vertexShader,
  fragmentShader
);

// Fix: Proper type extension for R3F
import { extend } from "@react-three/fiber";
import type { Texture } from "three";

extend({ TransitionMaterial });

type TransitionMaterialProps = {
  uProgress?: number;
  uTime?: number;
  uTex0?: Texture;
  uTex1?: Texture;
  uTex2?: Texture;
  uTex3?: Texture;
  uTex4?: Texture;
  uDepth?: Texture;
  uDisplacementStrength?: number;
} & React.JSX.IntrinsicElements["shaderMaterial"];

declare module "@react-three/fiber" {
  interface ThreeElements {
    transitionMaterial: TransitionMaterialProps;
  }
}

const ASSET_PATH = "https://www.razisyed.cv/experiments/mountain-transition";

export default function Scene() {
  const meshRef = useRef<THREE.Mesh>(null);
  // Fix 'any' by typing the ref properly
  const materialRef = useRef<
    THREE.ShaderMaterial & { uProgress: number; uTime: number }
  >(null);
  const { viewport } = useThree();

  // Load Assets
  const tex0 = useVideoTexture(`${ASSET_PATH}/green.mp4`);
  const tex1 = useVideoTexture(`${ASSET_PATH}/snowy.mp4`);
  const tex2 = useVideoTexture(`${ASSET_PATH}/sunrise.mp4`);
  const tex3 = useVideoTexture(`${ASSET_PATH}/painting.mp4`);
  const tex4 = useVideoTexture(`${ASSET_PATH}/painting2.mp4`);

  const depthTex = useTexture(`${ASSET_PATH}/depth-grayscale.png`);

  const textures = useMemo(
    () => [tex0, tex1, tex2, tex3, tex4],
    [tex0, tex1, tex2, tex3, tex4]
  );

  useEffect(() => {
    textures.forEach((tex) => {
      const video = tex.image as HTMLVideoElement;
      video.loop = true;
      video.muted = true;
      video.play();
    });
  }, [textures]);

  useFrame((state) => {
    if (materialRef.current) {
      materialRef.current.uTime = state.clock.elapsedTime;
    }
  });

  useEffect(() => {
    const trigger = ScrollTrigger.create({
      trigger: "#mountain-scroll-container",
      start: "top top",
      end: "bottom bottom",
      scrub: 0.5,
      snap: {
        snapTo: 1 / 4,
        duration: { min: 0.1, max: 0.5 }, // Faster snap
        delay: 0.1, // Reduced delay for quicker response
        ease: "power1.inOut",
      },
      onUpdate: (self) => {
        if (materialRef.current) {
          materialRef.current.uProgress = self.progress;
        }
      },
    });

    return () => {
      trigger.kill();
    };
  }, []);

  return (
    <mesh position={[0, 0, 0]} ref={meshRef}>
      <planeGeometry args={[viewport.width, viewport.height, 128, 128]} />
      <transitionMaterial
        ref={materialRef}
        uDepth={depthTex}
        uDisplacementStrength={0.6}
        uTex0={tex0}
        uTex1={tex1}
        uTex2={tex2}
        uTex3={tex3}
        uTex4={tex4}
        wireframe={false}
      />
    </mesh>
  );
}

// Simplex 2D noise & FBM
const noiseBenchmark = `
vec3 permute(vec3 x) { return mod(((x*34.0)+1.0)*x, 289.0); }

float snoise(vec2 v){
  const vec4 C = vec4(0.211324865405187, 0.366025403784439,
           -0.577350269189626, 0.024390243902439);
  vec2 i  = floor(v + dot(v, C.yy) );
  vec2 x0 = v -   i + dot(i, C.xx);
  vec2 i1;
  i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;
  i = mod(i, 289.0);
  vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 ))
  + i.x + vec3(0.0, i1.x, 1.0 ));
  vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
  m = m*m ;
  m = m*m ;
  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;
  m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );
  vec3 g;
  g.x  = a0.x  * x0.x  + h.x  * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;
  return 130.0 * dot(m, g);
}

float fbm(vec2 x) {
    float v = 0.0;
    float a = 0.5;
    vec2 shift = vec2(100.0);
    mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.50));
    for (int i = 0; i < 4; ++i) { // 4 Octaves is enough for smooth mist
        v += a * snoise(x);
        x = rot * x * 2.0 + shift;
        a *= 0.5;
    }
    return v;
}
`;

export const vertexShader = `
  uniform sampler2D uDepth;
  uniform float uDisplacementStrength;
  uniform float uTime;

  varying vec2 vUv;
  varying float vDepth;

  void main() {
    vUv = uv;
    float depth = texture2D(uDepth, uv).r;
    vDepth = depth;
    vec3 pos = position;
    // Moderate displacement for volume
    pos.z += depth * uDisplacementStrength; 
    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
  }
`;

export const fragmentShader = `
  uniform float uProgress;
  uniform sampler2D uTex0;
  uniform sampler2D uTex1;
  uniform sampler2D uTex2;
  uniform sampler2D uTex3;
  uniform sampler2D uTex4;
  uniform sampler2D uDepth;
  uniform float uTime;

  varying vec2 vUv;
  varying float vDepth;

  ${noiseBenchmark}

  vec4 getTexture(int index, vec2 uv) {
    if (index == 0) return texture2D(uTex0, uv);
    if (index == 1) return texture2D(uTex1, uv);
    if (index == 2) return texture2D(uTex2, uv);
    if (index == 3) return texture2D(uTex3, uv);
    if (index == 4) return texture2D(uTex4, uv);
    return texture2D(uTex0, uv);
  }

  void main() {
    float totalScenes = 5.0;
    float rawP = uProgress * (totalScenes - 1.0);
    int index0 = int(floor(rawP));
    int index1 = int(ceil(rawP));
    float p = fract(rawP);

    vec4 col0 = getTexture(index0, vUv);
    vec4 col1 = getTexture(index1, vUv);

    // --- CINEMATIC MIST TRANSITION ---
    // Goal: A smooth, depth-aware blend.
    // Logic: Transition map = Depth (dominant) + Noise (organic variation).

    // Soft, large scale noise
    float noise = fbm(vUv * 3.0 + vec2(uTime * 0.05, 0.0)); 

    // Combine Depth and Noise.
    // User requested "Front to Back" transition.
    // vDepth: 1.0 = Near, 0.0 = Far.
    // We want Near to transition FIRST.
    // Logic: Transition happens when structure < threshold (creates mask=0 -> Col1).
    // As p increases, threshold increases (-0.2 -> 1.2).
    // So distinct values of 'structure' will follow the threshold.
    // Elements with LOW structure value will be caught by the threshold first.
    // So we want Foreground (Near) to have LOW structure.

    float structure = (1.0 - vDepth) * 0.8 + noise * 0.2; // Inverted Depth for Front-to-Back

    // P goes 0 -> 1.
    // Threshold sweeps from -0.2 to 1.2
    float threshold = p * 1.4 - 0.2;

    // Smoothness determines how "foggy" the specific transition line is
    float smoothness = 0.15;

    // Mix mask: 0 = Col0, 1 = Col1
    // structure > threshold ? 
    // If p=0, threshold=-0.2. structure (0..1) > -0.2. 
    // We want result to be Col0 (current).
    // So if structure > threshold, return Col0?
    // Let's use standard smoothstep logic.
    // factor = smoothstep(threshold - soft, threshold + soft, structure)
    // If p=0, threshold=-0.2. factor ~ 1.0. 
    // If p=1, threshold=1.2. factor ~ 0.0.
    // So factor goes 1 -> 0.

    float mask = smoothstep(threshold - smoothness, threshold + smoothness, structure);

    // mix(Col1, Col0, mask) -> 
    // mask=1 (start) -> Col0. 
    // mask=0 (end) -> Col1.

    gl_FragColor = mix(col1, col0, mask);
  }
`;
